-- Volume 3, 2024, pages 2-8: Response of Some Haematological Parameters in Adult Male Wistar Rats Fed Different Colour Seeded Zea mays L (Maize)
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'Response of Some Haematological Parameters in Adult Male Wistar Rats Fed Different Colour Seeded Zea mays L (Maize)', 'Otamere H.O., Vidona W.B., Shelu O.J., Ogbe O.C., Essu I.S.', 'Maize (Zea mays L.) is a globally consumed staple, with its nutritional composition —particularly carotenoid content—varying by kernel color. These differences may influence blood-related health markers, yet the haematological effects of coloured maize varieties remain unclear. This study investigated the influence of white and yellow maize -based diets on selected haematological parameters in adult male Wistar rats. Twenty-five rats were r andomly assigned to five groups; a control fed standard rat chow while groups 2 and 3 received diets containing 25% and 50% white seeded maize and groups 4 and 5 received 25% and 50% yellow seeded-maize for 21 days. Blood samples were collected post-treatment and analyzed for packed cell volume (PCV), hemoglobin (Hb), red blood cell count (RBC), white blood cell count (WBC), and platelet count using an automated hematology analyzer and the data analysed for statistical differences using ANOVA at p<0.05. There was a s ignificant reductions in PCV and RBC in the groups fed 50% white seeded-maize and 25% and 50% yellow-seeded maize compared with control. However, Hb, WBC, and platelet counts remained unaffected across all groups. These findings suggest anemic-inducing potential of high maize consumption ; particularly yellow seeded-maize. Thus, high maize content diet-especially yellow seeded-maize, may impair PCV and RBC, though immune and clotting functions appear unaffected in rats. Further research is needed to assess the nutrient profiles of these maize varieties and explore dietar y strategies to counter balance any negative effects.', 'otaharri2012@gmail.com', 2024, 3, '1', '2-8', '', 'uploads/AAUJMR_V3_I1/Paper 1. Otamere et al AAUJMR 3; 2-8.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'Response of Some Haematological Parameters in Adult Male Wistar Rats Fed Different Colour Seeded Zea mays L (Maize)' AND `year` = 2024 AND `volume` = 3 AND `issue` = '1'
);

-- Volume 3, 2024, pages 9-15: Moderate Exercise on Voluntary Apnea Duration in Healthy Adult Male Across a Spectrum of Body Mass Index
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'Moderate Exercise on Voluntary Apnea Duration in Healthy Adult Male Across a Spectrum of Body Mass Index', 'Omigie M.I., Edeha D.O., Alufohai P.I.', 'The cessation of breathing is called apnea or breath -holding. This study aimed to investigate the impact of moderate exercise on voluntary apnea duration in healthy adult males across a spectrum of Body Mass Index (BMI), to elucidate the physiological inte rplay between adiposity and respiratory-metabolic reserve. Thirty male subjects (aged 20 -30 years) were stratified into normal weight (n=10, BMI: 22.42 ±0.41 kg/m²), overweight (n=10, BMI: 27.47 ±0.45 kg/m²), and obese (n=10, BMI: 37.46±0.97 kg/m²) groups. The duration of voluntary apnea was measured at rest and immediately following a session of moderate exercise. Data were presented as Mean ± SEM and were compared using one-way ANOVA followed by Tukey’s post-hoc text at p<0.05. A significant decrease in apnea duration was seen after exercise compared to before exercise in all the groups. Also, there was a significant decreased in apnea duration in the overweight and obese groups when compared to the normal weight group . These findings demonstrate a n adiposit y dependent impairment of voluntary apnea capacity with increasing BMI, an effect markedly exacerbated by the metabolic stress of exercise. The results suggest that elevated adiposity, particularly obesity, critically erodes integrated cardiorespiratory and metabolic reserve, limiting the tolerance to respiratory challenges.', 'daniel.edeha@yahoo.com', 2024, 3, '1', '9-15', '', 'uploads/AAUJMR_V3_I1/Paper 2. Omigie et al AAUJMR 3; 9-15.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'Moderate Exercise on Voluntary Apnea Duration in Healthy Adult Male Across a Spectrum of Body Mass Index' AND `year` = 2024 AND `volume` = 3 AND `issue` = '1'
);

-- Volume 3, 2024, pages 16-23: Phytochemical, Toxicological and Haematological Potentials of Dacryodes edulis Seed in Carbon Tetrachloride Exposed Rats
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'Phytochemical, Toxicological and Haematological Potentials of Dacryodes edulis Seed in Carbon Tetrachloride Exposed Rats', 'Eidangbe G.O., Obasi I.O., Eidangbe R.C.', 'This study evaluates the phytochemical and toxicological potentials of ethanolic seed extract of Dacryodes edulis (DE) and its effect and hematological profile of Carbon tetrachloride (CCl4) exposed male rats. Phytochemical studies were carried out on the seed and acute toxicity was determined using Lorke method. Wistar rats ( N=90; 180-200g) were distributed into 3 groups; control, CCl4 exposed (IP 1ml/kg in 1:1 olive oil every 72 hours in 3 doses) and CCl4 exposed treated DE (1500 mg/kg ). Blood samples were collected at days 1, 7, 14, 21 and 28 for the hematological variable herein investigated. The data were analyzed using ANOVA (SPSS Version 17.0) and LSD post hoc test at p≤ 0.05. Qualitative and quantitative phytochemical composition showed DE seeds to be a rich source of carbohydrate, Phenol, Alkaloid, Flavonoid and Tannins and safe at dose of 5000mg/kg body weight. CCl4 induced significant increase in white blood cell and neutrophil counts but decreased in red blood cell, hematocrite, platelet and lymphocytes counts. Treatment with DE resulted in mitigating the observed CCl4 induced alterations. Hence, DE possess phytochemical component that may improved CCl4 induced haematological alterations in rats.', 'dreidangbegeorgeo@gmail.com', 2024, 3, '1', '16-23', '', 'uploads/AAUJMR_V3_I1/Paper 3. Eidangbe et al AAUJMR 3; 16-23.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'Phytochemical, Toxicological and Haematological Potentials of Dacryodes edulis Seed in Carbon Tetrachloride Exposed Rats' AND `year` = 2024 AND `volume` = 3 AND `issue` = '1'
);

-- Volume 3, 2024, pages 24-29: Elemental Constituents, Proximate Composition and Phytochemical Levels of Roots of Elaeis guineensis (Palm Tree) and Cocos nucifera (Coconut)
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'Elemental Constituents, Proximate Composition and Phytochemical Levels of Roots of Elaeis guineensis (Palm Tree) and Cocos nucifera (Coconut)', 'Aguebor-Ogie B.N., Inegbedion A., Ukwuonwo-Ediale A.C.', 'This study aimed at ascertaining the nutritional value and medicinal properties of the roots of Elaeis guineensis (E. guineensis) and Cocos nucifera (C. nucifera). Roots of E. guineensis were collected from an average height tree while C. nucifera were from matured dwarf coconut trees growing within the University of Benin premises, Benin City, Nigeria. The samples were air -dried in the laboratory and blended into powder for the analyses. The phytochemical, proximate and elemental constituents were analyzed using standard analytical methods while the elemental composition was by flame photometry. The proximate composition of E. guineensis roots revealed moisture content (3.493 % ), crude pr otein (2.64 %), crude fibre (7.00 %), crude fat (0.80 %), ash (7.33 %), and carbohydrate (70.56 %). The result for proximate composition of C. nucifera revealed moisture content (3.15 %), crude protein (1.75 %), crude fibre (8.83 %), lipid profile (0.20 %), ash (2.33 %), and carbohydrate (71.75 %). While the elemental analysis revealed phosphorus (0.062 %), Calcium, Ca (0.012 %), Magnesium, Mg (0.126 %), and Iron, Fe (2.110 %). This study revealed that roots of both C. nucifera and E. guineensis contain bioactive compounds that can be harnessed for medicinal use and possible inclusion in diets.', 'nogiomwan.aguebor-ogie@uniben.edu.ng', 2024, 3, '1', '24-29', '', 'uploads/AAUJMR_V3_I1/Paper 4. Aguebo-Ogie et al AAUJMR 3; 24-29.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'Elemental Constituents, Proximate Composition and Phytochemical Levels of Roots of Elaeis guineensis (Palm Tree) and Cocos nucifera (Coconut)' AND `year` = 2024 AND `volume` = 3 AND `issue` = '1'
);

-- Volume 3, 2024, pages 30-36: Differential Effects of Dietary Ingestion of White and Brown Beans (Phaseolus vulgaris L) on Lipid Profile and Adipose Tissue Distribution in Male Wistar Rats
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'Differential Effects of Dietary Ingestion of White and Brown Beans (Phaseolus vulgaris L) on Lipid Profile and Adipose Tissue Distribution in Male Wistar Rats', 'Otamere H.O., Akpamu U., Ikhajiangbe H.I., Essu I.S.', 'This study investigated the impact of dietary consumption of white and brown beans ( Phaseolus vulgaris L) on lipid profile and adipose tissue d istribution in rats. Twenty-five male Wistar rats of comparable weights (100 ± 20g) were assigned to five groups ; a control, fed normal rat chow, test groups 2 and 3, fed 25% and 50% white beans- and 4 and 5, fed 25% and 50% brown beans- diets for 21 days. By 22nd day of diet consumption, blood samples were collected in plain bottles and centrifuge at 3000 rpm for 10 minutes to obtain serum for total cholesterol, triglycerides, and high- density lipoprotein estimation using commercial kits while low density lipoprotein (LDL) was calculated based using standard formula. The rats were di ssected to obtain and estimated thoracic and abdominal adipose tissues weight using electronic weighing scale. The result showed a significant decreased in body weight gain in the beans-fed groups. There was improved lipid profile, with significant decreased in blood glucose (50% white beans) , serum triglycerides ( 50% white beans), LDL cholesterol (50% brown beans), and abdominal adipose tissue weight (50% white and brown bean) compared with the control. T his study suggests that consumption of white or brown beans, especially at moderate to high dietary levels, may support metabolic health by modulating lipid metabolism, glucose homeostasis, and adipose tissue accumulation.', 'uwaifoh.akpamu@fuoye.edu.ng', 2024, 3, '1', '30-36', '', 'uploads/AAUJMR_V3_I1/Paper 5. Otamere et al AAUJMR 3; 30-36.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'Differential Effects of Dietary Ingestion of White and Brown Beans (Phaseolus vulgaris L) on Lipid Profile and Adipose Tissue Distribution in Male Wistar Rats' AND `year` = 2024 AND `volume` = 3 AND `issue` = '1'
);

-- Volume 3, 2024, pages 37-42: Assessment of Administration of Aqueous Extract of Garcinia Kola on the Liver and Kidney Function Parameters in Sprague Dawley Rats
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'Assessment of Administration of Aqueous Extract of Garcinia Kola on the Liver and Kidney Function Parameters in Sprague Dawley Rats', 'Adisa W.A., Blackie O.H., Idowu A.A.', 'This study investigated the effect of aqueous seed extract of Garcinia kola on the liver and kidney functions in rats. Eighteen female adults rats were divided into 3 groups ; a control, and two test groups treated with 0.5 or 1 mg/kg Garcinia kola extract using orogastric canula. Two weeks after treatment, blood samples were collected to estimate liver and kidney functions using standard laboratory procedures and the data analysed for significant different at p<0.05. Comparatively, there was a significant increase in serum alanine transaminase (ALT; 18.60±1.96 vs 16.00±1.79 vs 26.00±1.41 u/L), potassium (4.16±0.25 vs 4.62±0.11 vs 5.58±0.32 mmol/L), urea (27.60±12.34 vs 41.20±13.67 vs 110.00±14.65 g/dL) and creatinine (0.72±0.04 vs 0.88±0.37 vs 1.76±0.05g/dL) but no significant increase in aspartate transaminase (AST), Bilirubin, Albumin, Total Protein, sodium, chloride and bicarbonate compared with control. Garcinia kola extract has s timulating effect on serum ALT, urea and creatinine at a high dose and therefore should be consumed with moderation.', 'williamsadewumi@yahoo.com', 2024, 3, '1', '37-42', '', 'uploads/AAUJMR_V3_I1/Paper 6. Adisa et al AAUJMR 3; 37-42.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'Assessment of Administration of Aqueous Extract of Garcinia Kola on the Liver and Kidney Function Parameters in Sprague Dawley Rats' AND `year` = 2024 AND `volume` = 3 AND `issue` = '1'
);

-- Volume 3, 2024, pages 43-47: Cardiovascular Impact of Consumption of Sorghum Based Alcoholic Beverage (Burukutu) in Adult Male Wistar Rats
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'Cardiovascular Impact of Consumption of Sorghum Based Alcoholic Beverage (Burukutu) in Adult Male Wistar Rats', 'Oyakhire M.O., Ikhajiangbe H.I., Adie P.U., Ogboh C.B.', 'Alcohol production companies and business are making so much of profit from increased products demand but t he economic constrained have seek to dep end on the locally made version . Cardiovascular diseases are on the increase and lipid profile markers are suitable indicator for the determination of cardiovascular health. This study attempts to elucidate the impact of sorghum based alcoholic beverage ( Burukutu) on cardiovascular health through changes in serum lipid s in rats. Thirty male Wistar rats weighing 80-100g were divided into 6 groups; a control, groups treated with 5% Burukutu every other day , weekend and those treated with 1%, 5% and 25% Burukutu daily. At the end of 14 days treatment, blood samples were collected for assessment of serum lipid profile. The data was subjected to ANOVA at p ≤0.05 significance. The results showed that serum total cholesterol, triglyceride, high density lipoprotein (HDL) and low density lipoprotein (LDL) levels in rats administered Burukutu were not significantly different compared with the control. However, total cholesterol, triglyceride, and high density lipoprotein levels were likely decreased following weekend ingestions compared to every other day with LDL increased following weekend ingestions compared to every other day. These findings suggest that ingestion of Burukutu may not affect the functionality of the cardiovascular system in rats. However, every other day ingestion and weekend ingestion s are most likely to have significant impact on the cardiovascular system considering their effect of triglyceride and total cholesterol and LDL respectively.', 'oyakhireosenimusa@aauekpoma.edu.ng', 2024, 3, '1', '43-47', '', 'uploads/AAUJMR_V3_I1/Paper 7. Oyakhare et al AAUJMR 3; 43-8.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'Cardiovascular Impact of Consumption of Sorghum Based Alcoholic Beverage (Burukutu) in Adult Male Wistar Rats' AND `year` = 2024 AND `volume` = 3 AND `issue` = '1'
);

-- Volume 3, 2024, pages 48-52: Geophagic Use of Calabash Chalk on Sperm Characteristics and Testicular Histoarchitecture of Adult Wistar Rats
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'Geophagic Use of Calabash Chalk on Sperm Characteristics and Testicular Histoarchitecture of Adult Wistar Rats', 'Odiase D.E., Maduakolam J.D., Zekere C.S.', 'Calabash chalk is composed of aluminium silicate hydroxide and belongs to the Kaolin clay family, naturally occurring mineral and it is derived from fossilized seashells. It is composed of several elements and also constitutes major remedy for morning sickness. The aim of this study is to evaluate the effects of calabash chalk on sperm characteristics and the histology of the testis of adult Wistar rats. Twenty (20) matured Wistar rats were randomly assigned into four groups of five rats each (A -D). Group A served as the control while group B, C and D served as the test groups and were treated with 100 mg/kg, 200mg/kg and 400mg/kg of calabash chalk for 8 weeks. Semen were collected for sperm parameters analysis and the testes harvested for histological processing. There was no significant change (P>0.05) in the sperm parameters, luminal contents and histo-architecture of the testes of the treatment groups compare with the control group. These findings concluded that calabash chalk has no significant deleterious effects on the sperm content and testicular histoarchitecture of adult Wistar rats.', 'daniel.odiase@uniben.edu', 2024, 3, '1', '48-52', '', 'uploads/AAUJMR_V3_I1/Paper 8. Odiase et al AAUJMR 3; 48-52.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'Geophagic Use of Calabash Chalk on Sperm Characteristics and Testicular Histoarchitecture of Adult Wistar Rats' AND `year` = 2024 AND `volume` = 3 AND `issue` = '1'
);

-- Volume 3, 2024, pages 53-58: Effect of Ethanolic Leaf Extract of Telfairia Occidentalis on Lipid Profile in Experimentally Induced Chronic Stressed Rat
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'Effect of Ethanolic Leaf Extract of Telfairia Occidentalis on Lipid Profile in Experimentally Induced Chronic Stressed Rat', 'Imhantabhunu E.S., Edwin E.E., Omodiagbe O., Okonofua D.E., Omogbemhe S.A.', 'This study aimed to investigate the effect of the ethanol leaf extract of Telfairia occidentalis (T. occidentalis) on lipid profile in experimentally induced chronic stressed rats. In a bid to achieve this objectives, 30 male Wista r rats were randomly assigned to six groups: negative control, positive control (untreated chronic stress), standard drug treated (sertraline 25mg/kg), and three test groups treated with 100, 200, or 400 mg/kg of T. occidentalis extract. Chronic stress was induced through immobility/retrain stress 2 hours daily for 21 days. By day 22, behavioural studies were carried out using elevated plus maize and open field boxes and blood samples obtained for lipid profile assessment and the data analysed for significant different at p<0.05 . Behavioral studies revealed low and high doses of T. occidentalis extracts to mitigated anxiety -like behaviors induced by chronic stress. There was a non-significant different in serum total cholesterol , triglyceride, High density lipoprotein (HDL) and low density lipoprotein levels between groups, however, there were relatively lower in the T. occidentalis treated groups compared with the positive control; except for serum HDL level. This findings suggest that ethanol leaf extract of T. occidentalis have potential therapeutic benefit in managing chronic stress induced anxiety , but it effect in liver lipid is indecisive and hence the need for further studies.', 'Sammy.ehis@yahoo.com', 2024, 3, '1', '53-58', '', 'uploads/AAUJMR_V3_I1/Paper 9. Imhantabhunu et al AAUJMR 3; 53-58.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'Effect of Ethanolic Leaf Extract of Telfairia Occidentalis on Lipid Profile in Experimentally Induced Chronic Stressed Rat' AND `year` = 2024 AND `volume` = 3 AND `issue` = '1'
);

-- Volume 4, 2025, pages 2-13: The Role of Diet Containing Seeds of Elaeis Guineensis on Heamatological and Serum Biochemical Variables During Intermittent Fasting
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'The Role of Diet Containing Seeds of Elaeis Guineensis on Heamatological and Serum Biochemical Variables During Intermittent Fasting', 'Omayone T.P.', 'This study evaluated the effects of dietary Elaeis guineensis seed supplementation, with and without alternate-day intermittent fasting (IF), on anthropometric measurements, haematological indices, and serum biochemical parameters in rats. Thirty-six female rats weighing 80–110g were assigned to six groups: Control, IF, 5% palm kernel seed diet (PKSD), 5% PKSD + IF, 15% PKSD, and 15% PKSD + IF for eight weeks. Anthropometric parameters were measured weekly and blood samples collected at weeks 4 and 8 for haematological and serum liver enzymes estimation . Data were analyzed using one -way analysis of variance followed by Tukey''s post hoc test, with statistical significance set at p<0.05. The 5% PKSD presented highest body weight gain while 15% PKSD + IF group showed the least weight gain and abdominal circumference. At four weeks, IF significantly increased packed cell volume (PCV) and haemoglobin concentration, while PKSD supplementation increased white blood cell cou nts, an effect attenuated by concurrent IF. By week eight, IF significantly reduced red blood cell count and PCV, whereas PKSD supplementation maintained significantly higher haemoglobin concentrations. Serum alanine aminotransferase and aspartate aminotransferase activities were elevated in the IF group but were si gnificantly reduced in PKSD- supplemented groups, with the greatest reduction observed in the 5% PKSD + IF group. Dietary supplementation with Elaeis guineensis seed ameliorated fasting -induced alterations in haematological indices and reduced elevations in liver enzyme activities, suggesting protective effects on erythropoietic function and hepatic integrity and may serve as functional dietary component for mitigating haematological and hepatic effects associated with alternate-day IF.', 'tpomayone@futa.edu.ng', 2025, 4, '1', '2-13', '', 'uploads/AAUJMR_V4_I1/Paper 1. Omayane et al AAUJMR 4 Pp 2-13.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'The Role of Diet Containing Seeds of Elaeis Guineensis on Heamatological and Serum Biochemical Variables During Intermittent Fasting' AND `year` = 2025 AND `volume` = 4 AND `issue` = '1'
);

-- Volume 4, 2025, pages 14-20: Comparative Effects of Frying, Boiling and Curing on Lipid Oxidation in Chicken Meat Using the TBARS Assay
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'Comparative Effects of Frying, Boiling and Curing on Lipid Oxidation in Chicken Meat Using the TBARS Assay', 'Inegbedion A., Aguebor-Ogie N.B.', 'Chicken meat is an important source of high -quality protein and essential nutrients; however, thermal processing and curing may promote lipid oxidation, thereby affecting its nutritional quality and shelf stability. This study evaluated the effects of boiling, frying, and curing on lipid oxidation in chicken meat using malondialdehyde (MDA) concentration as an indicator of oxidative deterioration. Fresh chicken meat samples were processed into five treatment groups: raw, raw - cured, boiled, fried, and boiled–fried cured. Lipids were extracted using the Folch method, and lipid oxidation was quantified by the thiobarbituric acid reactive substances (TBARS) assay, with absorbance measured spectrophotometrically at 532 nm. The results demonstrated that frying and curing significantly increased (P < 0.05) MDA concentrations compared with boiled samples, indicating greater lipid peroxidation following these processing methods. In contrast, boiling produced the lowest level of lipid oxidation, suggesting that it better preserves lipid stability during processing. These findings indicate that processing methods markedly influence the oxidative stability of chicken meat and that high -temperature frying and curing may accelerate lipid deterioration. Boiling may therefore be a preferable processing method for minimizing lipid oxidation and preserving the nutritional quality of chicken meat', 'mails4augusta@yahoo.com', 2025, 4, '1', '14-20', '', 'uploads/AAUJMR_V4_I1/Paper 2. Inegbedion et al AAUJMR 4 Pp 14-20.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'Comparative Effects of Frying, Boiling and Curing on Lipid Oxidation in Chicken Meat Using the TBARS Assay' AND `year` = 2025 AND `volume` = 4 AND `issue` = '1'
);

-- Volume 4, 2025, pages 21-32: Evaluation of Seminal Fluid Analysis among Men Experiencing Immunological Infertility in South-West Nigeria
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'Evaluation of Seminal Fluid Analysis among Men Experiencing Immunological Infertility in South-West Nigeria', 'Ojerinde O.A., Bakare O.C., George V.E., Onwuamah C.K., Omidiran C.T., Ojerinde O.V., Aderemi E.O., Sulaiman A.G., Ogidi V.N., Agbolade O.M., Alagbe D.O.', 'Immunological infertility is an important but under -investigated cause of male infertility, particularly with respect to antisperm antibodies (ASA) and their relationship with seminal fluid characteristics. This study compares serum ASA levels and seminal fluid parameters in men with immunological infertility and fertile controls. The case–control study involv ed 32 men each experiencing infertility and fertile controls, recruited from South -West Nigeria using purposive sampling. Seminal fluid was analysed and serum ASA concentration quantified using enzyme- linked immunosorbent assay. Data were analysed in R; Fisher''s exact test, the Shapiro –Wilk test, the Mann –Whitney U test, and Spearman''s rank correlation were used as appropriate, with significance set at p < 0.05. Serum ASA levels were significantly higher among men experiencing immunological infertility than fertile controls. Significant differences between group were observed in semen volume, total motility, and normal sperm morphology, whereas progressive motility and sperm concentration did not differ significantly. Although most seminal fluid parameters among men experiencing immunological infertility met or exceeded the WHO 2021 lower reference values, several were nonetheless significantly lower than those of fertile controls. Serum ASA levels showed significant negative correlations with total motility (r = -0.18), normal sperm morphology (r = -0.31), and sp erm concentration (r = -0.14). Serum ASA levels are associated with selected seminal fluid characteristics among men with immunological infertility, even when conventional semen parameters remain within WHO reference limits. These findings support incorporating immunological assessment alongside conventional seminal fluid analysis in the investigation of male infertility.', 'kunle.ojerinde@fuoye.edu.ng', 2025, 4, '1', '21-32', '', 'uploads/AAUJMR_V4_I1/Paper 3 Ojerinde et al AAUJMR 4 Pp 21-32.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'Evaluation of Seminal Fluid Analysis among Men Experiencing Immunological Infertility in South-West Nigeria' AND `year` = 2025 AND `volume` = 4 AND `issue` = '1'
);

-- Volume 4, 2025, pages 33-41: Zingiber officinale Ameliorates Oxidative Stress in Adult Wistar Rats with Cytoarchitectural Distortion of the Pituitary Gland
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'Zingiber officinale Ameliorates Oxidative Stress in Adult Wistar Rats with Cytoarchitectural Distortion of the Pituitary Gland', 'Olugbenga M.A., Ekibade P.N., Olabanji O.J., Eromosele M.O., Okosun M.', 'This study investigated the dose -dependent effects of Zingiber officinale (Ginger) on oxidative stress biomarkers and pituitary histoarchitecture in rats. Fifteen adult female Wistar rats were randomly assigned to three groups ; control, 100 mg/kg and 300 mg/kg body weight of Zingiber officinale extract orally for 14 days. Body weights were monitored and at the end of treatment, blood samples were collected for the determination of serum malondialdehyde, catalase (CAT), reduced glutathione (GSH), and superoxide dismutase (SOD), while the pituitary glands were harvested for histological examination. Data wer e analysed using appropriate statistical methods, with statistical significance set at p < 0.05. Administration of Zingiber officinale resulted in a dose- dependent reduction in body weight gain and pituitary gland weight. Catalase activity increased in treated rats, whereas GSH and SOD activities declined relative to the control group. Malondialdehyde levels were lower in the treated groups, although differences were not statistically significant. Histological examination revealed varying degrees of cytoarchitectura l distortion and inflammatory cell infiltration in the pituitary gland, with the most severe alterations occurring in rats administered 300 mg/kg extract. Zingiber officinale exhibited dose -dependent effects on oxidative stress biomarkers and pituitary histoarchitecture in adult female Wistar rats. While the extract enhanced catalase activity and showed evidence of reduced lipid peroxidation, the concomitant reductions in GSH and SOD activities together with histological alterations suggest that higher doses may adversely affect pituitary integrity. These findings highlight the importance of dose consideration when using Zingiber officinale for its therapeutic benefits.', 'maryolugbenga@aauekpoma.edu.ng', 2025, 4, '1', '33-41', '', 'uploads/AAUJMR_V4_I1/Paper 4. Olugbenga et al AAUJMR 4 Pp 33-41.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'Zingiber officinale Ameliorates Oxidative Stress in Adult Wistar Rats with Cytoarchitectural Distortion of the Pituitary Gland' AND `year` = 2025 AND `volume` = 4 AND `issue` = '1'
);

-- Volume 4, 2025, pages 42-49: Hematological Evaluation of the Toxicity of Icacina Trichantha Ethanolic Root Extract in Rats
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'Hematological Evaluation of the Toxicity of Icacina Trichantha Ethanolic Root Extract in Rats', 'Eseine-Aloja C.E., Ugbeni O.C., Ujaddughe M.O., Shelu J.O.', 'Icacina trichantha is widely used in traditional medicine; however, its haematological safety profile remains inadequately characterized. This study evaluated the haematological effects of sub -acute oral administration of Icacina trichantha root ethanolic extract (ITREE) in rats. Twelve adult male Wistar rats were allocated into four groups; control, 200, 500, and 1000 mg/kg ITREE treated (orally) for 28 days. Thereafter, blood samples were collected for haematological analysis using an automated haematology analyzer. Data were analysed using ANOVA followed by the Least Significant Difference post-hoc test, with statistical significance set at p < 0.05. Administration of ITREE did not produce significant changes in red blood cell count, haemoglobin concentration, total white blood cell count, or platelet count. However, significant dose-dependent reductions were observed in haematocrit (43.30 - 44.23% vs. 47.33%) and mean corpuscular volume (56.27 - 59.97 fL vs. 62.36 fL), while mean corpuscular haemoglobin concentration increased significantly at the highest dose (37.08 g/dL vs. 33.83 g/dL). These findings indicate that sub -acute administration of ITREE at lower doses does not adversely affect major haematological parameters, suggesting a favourable haematological safety profile under the conditions of this study. Nevertheless, the dose- dependent alterations in erythrocyte indices observed at 500 and 1000 mg/kg may indicate early microcytic changes associated with higher levels of exposure. Further l ong-term and mechanistic studies are therefore recommended to elucidate the underlying mechanisms and establish the chronic haematological safety of the extract.', 'cee-aloja@aauekpoma.edu.ng', 2025, 4, '1', '42-49', '', 'uploads/AAUJMR_V4_I1/Paper 5. Eseine-Aloja et al AAUJMR 4 Pp 42-49.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'Hematological Evaluation of the Toxicity of Icacina Trichantha Ethanolic Root Extract in Rats' AND `year` = 2025 AND `volume` = 4 AND `issue` = '1'
);

-- Volume 4, 2025, pages 50-58: Impact of Artemether-Lumefantrine on Oxidative Stress Markers in Aspirin-Induced Gastric Ulcerated Rat
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'Impact of Artemether-Lumefantrine on Oxidative Stress Markers in Aspirin-Induced Gastric Ulcerated Rat', 'Adefisayo M.A., Olaiya O.L.', 'Artemether–Lumefantrine (AL), the first-line artemisinin-based combination therapy (ACT) for the treatment of uncomplicated malaria, exerts its antimalarial effect partly through the generation of reactive oxygen species. Although this mechanism is benefic ial for parasite clearance, it may also induce oxidative stress in host tissues. This study investigated the effects of AL on oxidative stress markers and gastric ulcer index in aspirin -induced gastric ulceration in Wistar rats. Twenty adult male Wistar ra ts were randomly assigned to four groups (n = 5 per group): normal control, AL - treated, ulcer control, and ulcer + AL -treated groups. Gastric ulceration was induced with aspirin (300 mg/kg) following overnight fasting. Artemether –Lumefantrine (2.3/27.4 mg/ kg) was administered orally once daily for three consecutive days to the appropriate groups after ulcer induction. Gastric tissues were harvested for the determination of malondialdehyde (MDA), reduced glutathione (GSH), and ulcer index, followed by histopathological examination. Data were analysed using one -way analysis of variance followed by Tukey''s post hoc test, with statistical significance set at P < 0.05. AL-treated ulcerated rats showed significantly increased MDA levels and ulcer indices, together with significantly reduced GSH concentrations, compared with the normal control group (P < 0.05). Histopathological examination revealed marked inflammatory cell infiltration, epithelial disruption, and tissue damage in the gastric mucosa of ulcerated rats treated with AL. These findings suggest that AL may enhance oxidative stress and aggrav ate gastric mucosal injury in the presence of pre-existing ulceration under the experimental conditions of this study.', 'maadefisayo@futa.edu.ng', 2025, 4, '1', '50-58', '', 'uploads/AAUJMR_V4_I1/Paper 6. Adefisayo and Olaiya AAUJMR 4 Pp 50-58.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'Impact of Artemether-Lumefantrine on Oxidative Stress Markers in Aspirin-Induced Gastric Ulcerated Rat' AND `year` = 2025 AND `volume` = 4 AND `issue` = '1'
);

-- Volume 4, 2025, pages 59-67: Pes Planus Morphology and Foot Injury Incidence in Athletic and Non-Athletic Cohorts
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'Pes Planus Morphology and Foot Injury Incidence in Athletic and Non-Athletic Cohorts', 'Vidona W.B., Eghaghe J., Omoyibo C.A., Dare E.I.', 'Pes planus has been implicated as a potential risk factor for lower limb injuries, although available evidence remains inconsistent. This cross-sectional study investigated the prevalence of pes planus and its association with foot injuries in professional athletes and recreational non-athletes. A sample of 169 participants (18 years and above ) was stratified into two groups: professional athletes and recreational non-athletes. Stratified random sampling was employed to ensure that both groups are adequately represented. Data were collected using structured questionnaires, physical examinations to determine the prevalence, the occurrence and types of foot injuries, and socio -demographic characteristics. The data obtained was analyzed using SPSS version 24 statistical software. The findings revealed that 32% of the participants did not exhibit pes planus, 30.8% had no prior pes planus evaluation, and 36.7% were unaware of their pes planus status. A history of foot injury was reported by 52.7% of the participants, with sprains (24.3%) and fractures (20.1%) being the most frequently reported injury types. Chi -square analysis indicated no statistically significant association between the presence of pes planus and the occurrence of foot injuries (χ² = 0.331, df = 2, p = 0.848). Independent samples t -tests on foot measurements (width, length, and arch height) showed no significant differences between participants with and without foot injuries. These results suggest that pes planus may not be a significant indepe ndent risk factor for foot injuries in this population. The study underscores the complexity of injury etiology and highlights the potential influence of other biomechanical and environmental factors.', 'vidonanem@gmail.com', 2025, 4, '1', '59-67', '', 'uploads/AAUJMR_V4_I1/Paper 7. Vidona AAUJMR 4. Pp 59-67.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'Pes Planus Morphology and Foot Injury Incidence in Athletic and Non-Athletic Cohorts' AND `year` = 2025 AND `volume` = 4 AND `issue` = '1'
);

-- Volume 4, 2025, pages 68-78: Comparative Analysis of the Effects of PRM1 and PRM2 Gene Polymorphisms on Sperm Parameters in Men with Unexplained Infertility in South-West Nigeria
INSERT INTO `manuscripts` (`title`, `authors`, `abstract`, `email`, `year`, `volume`, `issue`, `pages`, `category`, `pdf_upload`)
SELECT 'Comparative Analysis of the Effects of PRM1 and PRM2 Gene Polymorphisms on Sperm Parameters in Men with Unexplained Infertility in South-West Nigeria', 'Ojerinde O.A., Bakare O.C., Agbolade O.M., Onwuamah C.K., Omidiran C.T., Ojerinde O.V., Aderemi E.O., Ogidi V.N., Sulaiman A.G., George V.E., Alagbe D.O., Kemiki O.A.', 'Protamine 1 (PRM1) and Protamine 2 (PRM2) are essential for sperm chromatin condensation, and their disruption has been linked to impaired sperm function. Even though male factors account for nearly half of all infertility cases , comparative population-specific data on these genes are scarce. This study compared the effects of PRM1 and PRM2 polymorphisms on sperm parameters among men with unexplained infertility. A case –control study recruited 32 men each with unexplained infertility and fertile controls from South -West Nigerian. Semen was analysed and genomic DNA was extracted from blood, and the PRM1 (rs2301365) and PRM2 (rs1646023) polymorphisms were genotyped by real-time PCR allelic discrimination; 51 of 64 samples yielded successful genotypes (23 cases, 28 controls). Data were analysed in R (v4.5.1) using Mann–Whitney U test, Fisher''s exact test, chi -square test, and Hardy –Weinberg equilibrium testing, with significance set at p < .05. Normal sperm morphology, motility, and volume were significantly lower among cases than controls while progressive motility and concentration did not differ significantly. The PRM1 polymorphism was in Hardy –Weinberg equilibrium (χ² = 0.2008, p = .654) but showed no significant association with infertility at the genotype level (OR = 0.78, 95% CI: 0.17 –3.48, p = .749) or allele level (χ² = 0.132, p = .716). The PRM2 locus was monomorphic (100% CC genotype) in both groups, precluding association testing. Conclusively, men with unexplained infertility have measurably poorer sperm morphology, motility, and volume than fertile controls, but these differences could not be explained by PRM1 rs2301365 genotype.', 'Kunle.ojerinde@fuoye.edu.ng', 2025, 4, '1', '68-78', '', 'uploads/AAUJMR_V4_I1/Paper 8. Ojerinde et al AAUJMR 4 (1) 68-78.pdf'
WHERE NOT EXISTS (
    SELECT 1 FROM `manuscripts`
    WHERE `title` = 'Comparative Analysis of the Effects of PRM1 and PRM2 Gene Polymorphisms on Sperm Parameters in Men with Unexplained Infertility in South-West Nigeria' AND `year` = 2025 AND `volume` = 4 AND `issue` = '1'
);

COMMIT;
